insert into public.srd_equipment (id,nome,tipo,preco,custo_po,descricao,srd_source_url,categoria,detalhes) values
('srd35_magic_belt_monk_s','Belt, monk’s','magic_item',13000,13000,'This simple rope belt, when wrapped around a character’s waist, confers great ability in unarmed combat. The wearer’s AC and unarmed damage is treated as a monk of five levels higher. If donned by a character with the Stunning Fist feat, the belt lets her make one additional stunning attack per day. If the character is not a monk, she gains the AC and unarmed damage of a 5th-level monk. This AC bonus functions just like the monk’s AC bonus.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-v-wondrous-items.md','wondrous_items','{"source_file":"magic-items-v-wondrous-items.md","source_table":"Table: Medium Wondrous Items","market_price":"13,000 gp","roll_result":"39","raw_table_row":["39","Belt, monk’s","13,000 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
('srd35_magic_gem_of_brightness','Gem of brightness','magic_item',13000,13000,'This crystal appears to be a long, rough prism. Upon utterance of a command word, the crystal emits bright light of one of three sorts.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-v-wondrous-items.md','wondrous_items','{"source_file":"magic-items-v-wondrous-items.md","source_table":"Table: Medium Wondrous Items","market_price":"13,000 gp","roll_result":"40","raw_table_row":["40","Gem of brightness","13,000 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
('srd35_magic_lyre_of_building','Lyre of building','magic_item',13000,13000,'If the proper chords are struck, a single use of this lyre negates any attacks made against all inanimate construction (walls, roof, floor, and so on) within 300 feet. This includes the effects of a horn of blasting, a disintegrate spell, or an attack from a ram or similar siege weapon. The lyre can be used in this way once per day, with the protection lasting for 30 minutes.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-v-wondrous-items.md','wondrous_items','{"source_file":"magic-items-v-wondrous-items.md","source_table":"Table: Medium Wondrous Items","market_price":"13,000 gp","roll_result":"41","raw_table_row":["41","Lyre of building","13,000 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
('srd35_magic_cloak_of_arachnida','Cloak of arachnida','magic_item',14000,14000,'This black garment, embroidered with a weblike pattern in silk, gives the wearer the ability to climb as if a spider climb spell had been placed upon her. In addition, the cloak grants her immunity to entrapment by web spells or webs of any sort—she can actually move in webs at half her normal speed. Once per day, the wearer of this cloak can cast web. She also gains a +2 luck bonus on all Fortitude saves against poison from spiders.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-v-wondrous-items.md','wondrous_items','{"source_file":"magic-items-v-wondrous-items.md","source_table":"Table: Medium Wondrous Items","market_price":"14,000 gp","roll_result":"42","raw_table_row":["42","Cloak of arachnida","14,000 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
('srd35_magic_stone_horse_destrier','Stone horse, destrier','magic_item',14800,14800,'Listed in Table: Medium Wondrous Items; market price 14,800 gp. The specific item entry is not individually written out in this SRD table.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-v-wondrous-items.md','wondrous_items','{"source_file":"magic-items-v-wondrous-items.md","source_table":"Table: Medium Wondrous Items","market_price":"14,800 gp","roll_result":"43","raw_table_row":["43","Stone horse, destrier","14,800 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":false}'::jsonb),
('srd35_magic_belt_of_dwarvenkind','Belt of dwarvenkind','magic_item',14900,14900,'This belt gives the wearer a +4 competence bonus on Charisma checks and Charisma-based skill checks as they relate to dealing with dwarves, a +2 competence bonus on similar checks when dealing with gnomes and halflings, and a –2 competence penalty on similar checks when dealing with anyone else. The wearer can understand, speak, and read Dwarven. If the wearer is not a dwarf, he gains 60-foot darkvision, dwarven stonecunning, a +2 enhancement bonus to Constitution, and a +2 resistance bonus on saves against poison, spells, or spell-like effects.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-v-wondrous-items.md','wondrous_items','{"source_file":"magic-items-v-wondrous-items.md","source_table":"Table: Medium Wondrous Items","market_price":"14,900 gp","roll_result":"44","raw_table_row":["44","Belt of dwarvenkind","14,900 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
('srd35_magic_periapt_of_wound_closure','Periapt of wound closure','magic_item',15000,15000,'This stone is bright red and dangles on a gold chain. The wearer of this periapt automatically becomes stable if his hit points drop to between –1 and –9 inclusive. The periapt doubles the wearer’s normal rate of healing or allows normal healing of wounds that would not do so normally. Hit point damage that involves bleeding is negated for the wearer of the periapt, but he is still susceptible to damage from bleeding that causes Constitution loss, such as that dealt by a wounding weapon.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-v-wondrous-items.md','wondrous_items','{"source_file":"magic-items-v-wondrous-items.md","source_table":"Table: Medium Wondrous Items","market_price":"15,000 gp","roll_result":"45","raw_table_row":["45","Periapt of wound closure","15,000 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
('srd35_magic_horn_of_the_tritons','Horn of the tritons','magic_item',15100,15100,'This device is a conch shell that can be blown once per day except by a triton which can sound it three times per day. A horn of the tritons can perform any one of the following functions when blown.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-v-wondrous-items.md','wondrous_items','{"source_file":"magic-items-v-wondrous-items.md","source_table":"Table: Medium Wondrous Items","market_price":"15,100 gp","roll_result":"46","raw_table_row":["46","Horn of the tritons","15,100 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
('srd35_magic_pearl_of_the_sirines','Pearl of the sirines','magic_item',15300,15300,'This normal-seeming pearl is beautiful and worth at least 1,000 gp on that basis alone. If it is clasped firmly in hand or held to the breast while the possessor attempts actions related to the pearl’s powers, she understands and is able to employ the item.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-v-wondrous-items.md','wondrous_items','{"source_file":"magic-items-v-wondrous-items.md","source_table":"Table: Medium Wondrous Items","market_price":"15,300 gp","roll_result":"47","raw_table_row":["47","Pearl of the sirines","15,300 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
