('srd35_magic_cloak_of_displacement_major','Cloak of displacement, major','magic_item',50000,50000,'This item appears to be a normal cloak, but on command its magical properties distort and warp light waves. This displacement works just like the displacement spell and lasts for a total of 15 rounds per day, which the wearer can divide up as she sees fit.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-v-wondrous-items.md','wondrous_items','{"source_file":"magic-items-v-wondrous-items.md","source_table":"Table: Major Wondrous Items","market_price":"50,000 gp","roll_result":"31","raw_table_row":["31","Cloak of displacement, major","50,000 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
